// spec: .qa/e2e/specs/hunter-nda.md 1.2 · case: .qa/tests/hunter-nda/HN-1-2.md · ticket #d0bc44
// OPT-IN (QA_PAIR_NDA=1 + QA_PAIR_NDA_JOB + QA_PAIR_NDA_CANDIDATE), two roles (asUser). Written 2026-11-07, NOT run.
// Submit-wizard selectors as in tests/add-candidate/anon-owner-sees-no-employer-j49.spec.ts; status texts from
// d0bc44-A-submission-list-status-desktop.png — heal SELECTORS only.
// Creates data: anonymous submission of A's QA-AUTO candidate to B's job (cancelled by the refusal) → test-data-journal.log.
import { test, expect } from '../../fixtures';
import fs from 'fs';
import path from 'path';
import { PAIR, SKIP_MSG, ensurePending, bRefuses, bellText } from './_pair';

test.describe.configure({ mode: 'serial' });
const JOURNAL = path.join(__dirname, '../../test-data-journal.log');

test.describe('NDA between headhunters — held submission cancelled after refusal (#d0bc44)', () => {
  test.skip(!PAIR.enabled || !PAIR.job || !PAIR.candidate, `${SKIP_MSG} (1.2 also needs QA_PAIR_NDA_JOB and QA_PAIR_NDA_CANDIDATE)`);
  test.skip(!!PAIR.candidate && !PAIR.candidate.startsWith('QA-AUTO'), 'QA_PAIR_NDA_CANDIDATE must be a QA-AUTO candidate');

  let submitted = false;
  test.afterAll(() => {
    if (submitted) fs.appendFileSync(JOURNAL, `${new Date().toISOString()} ${PAIR.a} anonymous submission «${PAIR.candidate}» → ${PAIR.job} (hunter-nda 1.2 #d0bc44, cancelled by refusal of ${PAIR.b})\n`);
  });

  test('Held submission → B refuses → A: «בוטל • ה-NDA נדחה» + reason, bell «…ולכן ההגשה לא נשלחה» @desktop @data #d0bc44', async ({ asUser }) => {
    test.setTimeout(300_000);
    const a = await asUser(PAIR.a);
    const b = await asUser(PAIR.b);

    // Pair must not have an NDA in force (A's chat state)
    const state = await ensurePending(a);
    test.skip(state === 'in-force', 'pair NDA is in force — need a pair without NDA (see specs/hunter-nda.md)');

    // 1. A submits the candidate to B's job (anonymous, no NDA charge) → held for B's approval
    await a.goto(PAIR.job);
    const drawer = a.getByRole('dialog', { name: 'פרטי המשרה' });
    await expect(drawer).toBeVisible({ timeout: 30_000 });
    await drawer.getByRole('searchbox', { name: /חיפוש מועמד/ }).fill(PAIR.candidate);
    await drawer.getByRole('button', { name: `הגשת ${PAIR.candidate} למשרה` }).click();
    const choose = a.getByRole('dialog', { name: /^הגשת / }).last();
    await expect(choose.getByText('הגשה ראשונה להד האנטר הזה', { exact: false })).toBeVisible();
    await choose.getByText('פרופיל אנונימי', { exact: true }).click();
    await choose.getByText(/^אין צורך ב-NDA/).click();
    await choose.getByRole('button', { name: 'המשך', exact: true }).click();
    const form = a.getByRole('dialog', { name: /^הגשת מועמד/ }).last();
    const send = form.getByRole('button', { name: 'סיום והגשה', exact: true });
    await expect(send).toBeEnabled({ timeout: 90_000 });
    await send.click();
    await expect(form).toBeHidden({ timeout: 30_000 });
    submitted = true;

    // 2. B refuses (never approves)
    await bRefuses(b);

    // 3. A: panel row of the candidate on B's job (#d0bc44 п.2)
    await a.goto(PAIR.job);
    await expect(drawer).toBeVisible({ timeout: 30_000 });
    await drawer.getByRole('searchbox', { name: /חיפוש מועמד/ }).fill(PAIR.candidate);
    const row = drawer.getByRole('listitem').filter({ hasText: PAIR.candidate }).first()
      .or(drawer.locator('div').filter({ hasText: PAIR.candidate }).filter({ hasText: /בוטל/ }).last());
    await expect(row).toContainText(/בוטל\s*[·•]\s*ה-NDA נדחה/, { timeout: 30_000 });
    await expect(row).toContainText('סירבו לאשר את ה-NDA');
    await expect(row).not.toContainText('נשלח/ה');

    // 4. A bell: submission trigger wording (#d0bc44 п.3)
    const bell = await bellText(a);
    expect(bell, 'bell: «<B> סירבו …, ולכן ההגשה לא נשלחה»').toMatch(
      new RegExp(`${PAIR.bName} סירבו[^\\n]*ולכן ההגשה לא נשלחה`),
    );
  });
});
